from itertools import combinations
import random

def check_graph(edges, n=9):
    """Check if a graph satisfies all constraints."""
    # Build adjacency list
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check min degree >= 2
    for i in range(n):
        if len(adj[i]) < 2:
            return False, "min degree < 2"

    # Check max degree <= 3
    for i in range(n):
        if len(adj[i]) > 3:
            return False, "max degree > 3"

    # Check edges between 12 and 17
    if len(edges) < 12 or len(edges) > 17:
        return False, f"edges = {len(edges)} not in [12, 17]"

    # Check chromatic number >= 2 (always true if there's at least one edge)
    if len(edges) == 0:
        return False, "chromatic number < 2"

    # Check chromatic number <= 4
    # Use greedy coloring to get an upper bound
    # For exact chromatic number, we need to be more careful
    # But let's first try greedy
    colors = {}
    for node in range(n):
        used_colors = set()
        for neighbor in adj[node]:
            if neighbor in colors:
                used_colors.add(colors[neighbor])
        for c in range(1, 5):
            if c not in used_colors:
                colors[node] = c
                break
        else:
            return False, "chromatic number > 4 (greedy failed)"

    return True, "valid"

