from itertools import combinations

def verify_graph(edges, n=9):
    """Thoroughly verify all constraints."""
    # Build adjacency list
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check min degree >= 2
    degrees = [len(adj[i]) for i in range(n)]
    print(f"Degrees: {degrees}")
    print(f"Min degree: {min(degrees)}, Max degree: {max(degrees)}")

    if min(degrees) < 2:
        return False, "min degree < 2"
    if max(degrees) > 3:
        return False, "max degree > 3"

    # Check edges between 12 and 17
    print(f"Number of edges: {len(edges)}")
    if len(edges) < 12 or len(edges) > 17:
        return False, f"edges = {len(edges)} not in [12, 17]"

    # Check chromatic number
    # Try all possible colorings with 1, 2, 3, 4 colors
    def can_color_with_k(k):
        """Check if graph can be colored with k colors."""
        def backtrack(node, colors):
            if node == n:
                return True
            for c in range(k):
                valid = True
                for neighbor in adj[node]:
                    if neighbor < node and colors[neighbor] == c:
                        valid = False
                        break
                if valid:
                    colors[node] = c
                    if backtrack(node + 1, colors):
                        return True
                    colors[node] = -1
            return False

        return backtrack(0, [-1] * n)

    chromatic = None
    for k in range(1, 6):
        if can_color_with_k(k):
            chromatic = k
            break

    print(f"Chromatic number: {chromatic}")

    if chromatic is None or chromatic > 4:
        return False, "chromatic number > 4"
    if chromatic < 2:
        return False, "chromatic number < 2"

    # Check fixed edges
    edge_set = set(edges)
    if (0, 8) not in edge_set:
        return False, "missing fixed edge (0,8)"
    if (6, 7) not in edge_set:
        return False, "missing fixed edge (6,7)"

    return True, "all constraints satisfied"

